<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <iostream>
#include <cstdio>
#include <vector>
#include <deque>
#include <cstring>
using namespace std;

const int MAXN = 20;
const int MAXNODES = 2020;
const int INF = 3010;

vector<int> adj[MAXNODES];
int dist_to_sink[MAXNODES];
int partner[MAXNODES];
int ir[MAXN][MAXN], sc[MAXN][MAXN], pc[MAXN][MAXN];
char grid_s[MAXN][MAXN], grid_p[MAXN][MAXN];
int dd[MAXN][MAXN];
const int dx[4] = {0, 1, -1, 0};
const int dy[4] = {1, 0, 0, -1};
vector<int> src_nodes[MAXN][MAXN], dst_nodes[MAXN][MAXN];

void connect(int u, int v) {
    adj[u].push_back(v);
    adj[v].push_back(u);
}

int src_cnt, dst_cnt;

bool bfs_layered() {
    deque<int> q;
    for (int i = 1; i <= src_cnt; ++i) {
        if (partner[i] == 0) {
            dist_to_sink[i] = 0;
            q.push_back(i);
        } else {
            dist_to_sink[i] = INF;
        }
    }
    dist_to_sink[0] = INF;
    while (!q.empty()) {
        int u = q.front(); q.pop_front();
        if (dist_to_sink[u] < dist_to_sink[0]) {
            for (int v_node : adj[u]) {
                int v = partner[v_node];
                if (dist_to_sink[v] > dist_to_sink[u] + 1) {
                    dist_to_sink[v] = dist_to_sink[u] + 1;
                    q.push_back(v);
                }
            }
        }
    }
    return dist_to_sink[0] != INF;
}

bool dfs_augment(int u) {
    if (u == 0) return true;
    for (int v_node : adj[u]) {
        int v = partner[v_node];
        if (dist_to_sink[v] == dist_to_sink[u] + 1) {
            if (dfs_augment(v)) {
                partner[u] = v_node;
                partner[v_node] = u;
                return true;
            }
        }
    }
    return false;
}

int max_matching() {
    int match_count = 0;
    while (bfs_layered()) {
        for (int i = 1; i <= src_cnt; ++i) {
            if (partner[i] == 0) {
                match_count += dfs_augment(i);
            }
        }
    }
    return match_count;
}

int main() {
    int n, t;
    scanf("%d%d", &n, &t);
    memset(ir, t, sizeof(ir));
    for (int i = 1; i <= n; ++i) scanf("%s", grid_s[i] + 1);
    for (int i = 1; i <= n; ++i) scanf("%s", grid_p[i] + 1);
    int rx = 0, ry = 0;
    src_cnt = 1, dst_cnt = 1000;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid_s[i][j] == 'Z' || grid_s[i][j] == 'Y') {
                sc[i][j] = -1;
                ir[i][j] = 0;
            }
            if (grid_s[i][j] == 'Z') {
                rx = i; ry = j;
                ir[i][j] = 0;
            }
            if (isdigit(grid_s[i][j])) {
                sc[i][j] = grid_s[i][j] - '0';
                for (int k = 0; k < sc[i][j]; ++k)
                    src_nodes[i][j].push_back(src_cnt++);
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (isdigit(grid_p[i][j])) {
                pc[i][j] = grid_p[i][j] - '0';
                for (int k = 0; k < pc[i][j]; ++k)
                    dst_nodes[i][j].push_back(dst_cnt++);
            }
        }
    }
    deque<pair<int, int> > q;
    q.push_back({rx, ry});
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop_front();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (ir[nx][ny] > ir[x][y] + 1 && sc[nx][ny] != -1) {
                ir[nx][ny] = ir[x][y] + 1;
                q.push_back({nx, ny});
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (sc[i][j] > 0) {
                for (int x = 1; x <= n; ++x)
                    for (int y = 1; y <= n; ++y)
                        dd[x][y] = 100000;
                deque<pair<int, int> > dq;
                dd[i][j] = 0;
                dq.push_back({i, j});
                while (!dq.empty()) {
                    int x = dq.front().first, y = dq.front().second;
                    dq.pop_front();
                    for (auto src_id : src_nodes[i][j]) {
                        for (auto dst_id : dst_nodes[x][y]) {
                            connect(src_id, dst_id);
                        }
                    }
                    if (dd[x][y] == ir[x][y]) continue;
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + dx[d], ny = y + dy[d];
                        if (sc[nx][ny] != -1 && dd[nx][ny] > dd[x][y] + 1 && dd[x][y] + 1 <= ir[nx][ny]) {
                            dd[nx][ny] = dd[x][y] + 1;
                            dq.push_back({nx, ny});
                        }
                    }
                }
            }
        }
    }
    printf("%d", max_matching());
    return 0;
}
